'use strict';
(() => {
 const APPS=[
  {id:'messages',name:'Messages',caption:'A simple hello',icon:'message',colour:'moss'},
  {id:'calls',name:'Calls',caption:'Hear a familiar voice',icon:'call',colour:'leaf'},
  {id:'map',name:'Bay Maps',caption:'Find your next stop',icon:'map',colour:'sea'},
  {id:'bank',name:'Bay Bank',caption:'Make a little plan',icon:'bank',colour:'ochre'},
  {id:'jobs',name:'Daywork',caption:'A little more hustle',icon:'work',colour:'clay'},
  {id:'garage',name:'Bay Rides',caption:'Your way around town',icon:'car',colour:'sea'},
  {id:'shop',name:'Little Home',caption:'Comfort, delivered',icon:'home',colour:'rose'},
  {id:'notes',name:'Notes',caption:'Keep a thought',icon:'note',colour:'sand'},
  {id:'contacts',name:'Contacts',caption:'Your people',icon:'people',colour:'olive'},
  {id:'settings',name:'Settings',caption:'Make it yours',icon:'settings',colour:'stone'}
 ];
 const LOCAL=new Set(['map','bank','jobs','garage','shop','notes']);
 const paths={message:'<path d="M5 6h22v15H14l-7 6v-6H5z"/><path d="M10 11h12M10 16h8"/>',call:'<path d="m9 5 5 6-3 4c2 4 3 5 7 7l4-3 5 4c-1 6-5 7-10 4C8 23 3 14 5 8z"/>',map:'<path d="m4 7 8-3 8 4 8-3v20l-8 3-8-4-8 3zM12 4v20M20 8v20"/>',bank:'<path d="M4 12 16 4l12 8zM5 27h22M8 15v9M16 15v9M24 15v9"/>',work:'<rect x="4" y="10" width="24" height="18" rx="3"/><path d="M11 10V5h10v5M4 17c8 5 16 5 24 0M14 18v5h4v-5"/>',home:'<path d="m3 15 13-11 13 11M7 13v15h18V13M13 28V18h6v10"/>',note:'<rect x="6" y="4" width="21" height="25" rx="3"/><path d="M11 11h11M11 17h11M11 23h7M3 10h5M3 17h5M3 24h5"/>',people:'<circle cx="13" cy="11" r="5"/><path d="M3 28v-3a10 10 0 0 1 20 0v3M24 8a5 5 0 0 1 0 9M26 21a7 7 0 0 1 3 6"/>',settings:'<path d="m12 3-1 4-4 1-3 5 3 3-1 4 4 4 4-1 3 3 5-2 1-5 4-2-1-6-4-1-2-4z"/><circle cx="16" cy="15" r="5"/>'};
 paths.car='<path d="m4 16 4-9h16l4 9v10H4zM4 16h24M10 7v9M22 7v9M8 21h3M21 21h3M7 26v3M25 26v3"/>';
 function icon(name){return `<svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.home}</svg>`;}
 function title(name,kicker,description){return `<section class="phone-content local-app"><p class="phone-kicker">${kicker}</p><h2>${name}</h2><p class="app-description">${description}</p>`;}
 function rentInfo(){const weekly=state.home==='studio'?1400:900,nextDay=state.day+7-((state.day-1)%7);return {weekly,nextDay,shortfall:Math.max(0,weekly-state.money)};}
 function renderHome(host,context){const greeting=state.minutes<720?'Good morning':state.minutes<1080?'Good afternoon':'Good evening',name=state.name==='New neighbour'?'neighbour':state.name;host.innerHTML=`<section class="phone-home"><div class="home-welcome"><p class="phone-kicker">DAY ${String(state.day).padStart(2,'0')} · KORA BAY</p><h2>${greeting},<br>${context.escape(name)}.</h2><span class="home-sun">☀</span></div><button class="home-wallet" data-app="bank"><span><small>A LITTLE ROOM TO DREAM</small><b>${cash(state.money)}</b></span><span>↗</span></button><div class="phone-app-grid">${APPS.map(app=>`<button class="phone-app" data-app="${app.id}" aria-label="Open ${app.name}"><span class="app-icon ${app.colour}">${icon(app.icon)}</span><b>${app.name}</b></button>`).join('')}</div><p class="home-caption">A whole little world. Right here.</p></section>`;host.querySelectorAll('[data-app]').forEach(b=>b.onclick=()=>context.openApp(b.dataset.app));}
 function renderMap(host,context){const positions={home:[44,107],market:[101,47],cafe:[186,126],library:[86,183],waterfront:[238,191],studio:[205,55]},here=PLACES.find(p=>p.id===state.location);host.innerHTML=title('A city in your pocket.','BAY MAPS',`You’re at ${context.escape(here.name)}. Pick a place and use your selected ride.`)+`<svg class="phone-mini-map" viewBox="0 0 290 240" role="img" aria-label="Neighbourhood map showing all six places"><rect width="290" height="240" rx="14" fill="#dfe7cd"/><path d="M225 0Q170 77 237 119T244 240H290V0" fill="#bad5cc"/><path d="M0 82H206M0 153H240M66 0V240M144 0V240M220 0V90" stroke="#f9f5e3" stroke-width="13"/><path d="M0 82H206M0 153H240M66 0V240M144 0V240" stroke="#c6cfb0" stroke-width="1" stroke-dasharray="4 5"/>${PLACES.map(p=>{const [x,y]=positions[p.id];return `<circle cx="${x}" cy="${y}" r="${p.id===state.location?10:7}" fill="${p.id===state.location?'#c98d61':'#849d72'}" stroke="#f9f7e5" stroke-width="3"/><text x="${x}" y="${y-16}" text-anchor="middle" font-size="8" fill="#586f45">${p.name}</text>`;}).join('')}</svg><div class="app-map-list">${PLACES.map(p=>`<button class="app-destination" data-visit="${p.id}"><span>${p.icon}</span><span><b>${p.name}</b><small>${p.type}</small></span><em>${p.id===state.location?'Here':getTravelPlan(p.id).minutes+' min ↗'}</em></button>`).join('')}</div></section>`;host.querySelectorAll('[data-visit]').forEach(b=>b.onclick=()=>context.visit(b.dataset.visit));}
 function renderBank(host,context){const rent=rentInfo(),studio=state.home==='studio',progress=studio?100:Math.min(100,Math.floor(state.money/50));const entries=state.journal.filter(e=>/₭|shift|rent|bought|studio/i.test(e.text)).slice(0,6);host.innerHTML=title('Small steps. Big plans.','BAY BANK','Your game wallet, your rent, and a little room to plan ahead.')+`<div class="bank-card"><small>AVAILABLE BALANCE</small><h3>${cash(state.money)}</h3><span>KORA BAY · EVERYDAY WALLET</span></div><div class="app-stat-pair"><div><small>WEEKLY RENT</small><strong>${cash(rent.weekly)}</strong></div><div><small>NEXT RENT DAY</small><strong>Day ${rent.nextDay}</strong></div></div><div class="app-info-line ${rent.shortfall?'attention':''}">${rent.shortfall?`Set aside ${cash(rent.shortfall)} more before rent day.`:'Your next week’s rent is covered.'}</div><h3 class="phone-section-title">${studio?'A KEY OF YOUR OWN':'STUDIO SAVINGS'}</h3><div class="bank-goal"><b>${studio?'You made it to Olive Court.':cash(state.money)+' / ₭5,000'}</b><div class="progress"><span style="width:${progress}%"></span></div><small>${studio?'There’s still a whole life to build.':cash(Math.max(0,5000-state.money))+' until your studio deposit.'}</small></div><button class="phone-primary" id="walletJobs">Find a shift ↗</button><h3 class="phone-section-title">FROM YOUR JOURNAL</h3><div class="wallet-journal">${entries.map(e=>`<article><small>DAY ${e.day}</small><p>${context.escape(e.text)}</p></article>`).join('')||'<p>No money milestones yet. Your next shift can change that.</p>'}</div></section>`;$('#walletJobs').onclick=()=>context.openApp('jobs');}
 function renderJobs(host,context){host.innerHTML=title('Find your next little win.','DAYWORK','Pick up a shift, or build the skills that make your time worth more.')+`<div class="app-skill"><span>✦</span><div><b>Skill level ${state.skill} / 5</b><small>+${cash(state.skill*100)} on every shift</small></div></div>${[{place:'market',name:'Market helper',base:480,action:'market-work',text:'Help the stallholders keep the day moving.'},{place:'cafe',name:'Café crew',base:650,action:'cafe-work',text:'A busy counter. A good day’s honest work.'}].map(job=>{const commute=getTravelPlan(job.place),ready=state.energy>=25+commute.energy&&state.hunger>=20+commute.hunger;return `<article class="job-card"><div><span>${job.place==='market'?'▥':'☕'}</span><strong>${cash(job.base+state.skill*100)}<small>per shift</small></strong></div><h3>${job.name}</h3><p>${job.text}</p><small>4 hours · 25 energy · 20 fullness required${commute.minutes?' · +'+commute.minutes+' min '+commute.verb.toLowerCase():''}</small><button class="phone-primary" data-shift="${job.place}" data-action="${job.action}" ${ready?'':'disabled'}>${ready?'Work this shift ↗':'Eat or rest before a shift'}</button></article>`;}).join('')}<button class="app-study" id="studyDirections"><span>▤</span><div><b>Invest a little time in yourself</b><small>Visit the library · 2 hours of study · free</small></div><span>↗</span></button></section>`;host.querySelectorAll('[data-shift]').forEach(b=>b.onclick=()=>context.visit(b.dataset.shift,b.dataset.action));$('#studyDirections').onclick=()=>context.visit('library');}
 function renderShop(host,context){const stored=state.furniture.filter(i=>i.x===null).length;host.innerHTML=title('Make room for you.','LITTLE HOME','Buy a little comfort. New pieces go into your storage, ready to place.')+`<div class="shop-budget"><span>YOUR POCKET <b>${cash(state.money)}</b></span><small>${stored} ${stored===1?'piece':'pieces'} in storage</small></div><button class="phone-primary" id="decorateFromPhone">Open my apartment ↗</button><div class="phone-shop-grid">${FURNITURE.map(f=>`<article class="phone-shop-product"><div>${furnitureArt(f.id)}</div><h3>${f.name}</h3><small>${f.w} × ${f.h} floor squares</small><button data-phone-buy="${f.id}" ${state.money<f.price||state.furniture.length>=60?'disabled':''}>Buy · ${cash(f.price)}</button></article>`).join('')}</div></section>`;$('#decorateFromPhone').onclick=context.furnish;host.querySelectorAll('[data-phone-buy]').forEach(b=>b.onclick=()=>{const result=buyFurniture(b.dataset.phoneBuy);if(result.ok)renderShop(host,context);context.notify(result.ok?'Bought! Your new piece is in storage. Open your apartment to place it.':result.message);});}
 function renderNotes(host){host.innerHTML=title('Keep a little thought.','NOTES','Plans, reminders, or the name of that person you just met.')+'<label class="sr-only" for="phoneNotes">Your personal notes</label><textarea id="phoneNotes" maxlength="4000" placeholder="A few things for tomorrow…&#10;&#10;Save for a desk.&#10;Say hello to Ada.&#10;Take the long way home."></textarea><div class="notes-footer"><span id="notesSaveStatus" role="status">Saved with your story in this browser</span><span id="notesCount"></span></div></section>';$('#phoneNotes').value=typeof state.phoneNotes==='string'?state.phoneNotes:'';$('#notesCount').textContent=$('#phoneNotes').value.length+' / 4,000';$('#phoneNotes').oninput=()=>{state.phoneNotes=$('#phoneNotes').value.slice(0,4000);const saved=save();$('#notesSaveStatus').textContent=saved===false?'Browser saving is unavailable. Copy your notes before closing.':'Saved with your story in this browser';$('#notesCount').textContent=state.phoneNotes.length+' / 4,000';};}
 function renderGarage(host,context){const active=VEHICLES.find(v=>v.id===state.activeTransport),plan=getTravelPlan();host.innerHTML=title('A little further. A little faster.','BAY RIDES','Buy a ride, choose how to travel, and keep your tank topped up.')+`<div class="garage-wallet"><span>YOUR POCKET</span><b>${cash(state.money)}</b></div><div class="garage-current"><small>YOUR NEXT TRIP</small><h3>${plan.name} · ${plan.minutes} min</h3><p>${plan.reason||active?.description||'A walk is always free. Take your time and enjoy the neighbourhood.'}</p></div><button class="garage-walk ${state.activeTransport==='walk'?'chosen':''}" id="chooseWalking"><span>↗</span><div><b>Go on foot</b><small>15 min · 2 energy · no fuel</small></div><em>${state.activeTransport==='walk'?'Selected':'Choose'}</em></button>${VEHICLES.map(v=>{const owned=state.vehicles.find(o=>o.id===v.id),selected=state.activeTransport===v.id;const topup=owned?Math.min(25,100-owned.fuel):25;return `<article class="vehicle-card ${selected?'selected':''}"><div class="vehicle-display">${vehicleArt(v.id)}<span>${selected?'YOUR SELECTED RIDE':owned?'IN YOUR GARAGE':v.type.toUpperCase()}</span></div><h3>${v.name}</h3><p>${v.description}</p><div class="vehicle-specs"><span>${v.minutes} min / trip</span><span>${v.energy} energy</span><span>${v.fuelUse?v.fuelUse+'% fuel / trip':'No fuel needed'}</span></div>${owned?`${v.fuelUse?`<div class="vehicle-tank"><span>Fuel <b>${owned.fuel}%</b></span><div><i style="width:${owned.fuel}%"></i></div></div>`:''}<button class="phone-primary" data-choose-ride="${v.id}" ${selected?'disabled':''}>${selected?'Selected for travel':'Use this ride ↗'}</button>${v.fuelUse?`<button class="phone-link" data-refuel="${v.id}" ${topup?'':'disabled'}>${topup?'Add '+topup+'% fuel · '+cash(topup*v.refuelRate):'Tank full'}</button>`:''}`:`<button class="phone-primary" data-buy-ride="${v.id}" ${state.money<v.price?'disabled':''}>Buy & use · ${cash(v.price)}</button>`}</article>`;}).join('')}<p class="phone-small-print">Choose a destination on the city map or in Bay Maps. If a tank runs low, you can always walk and refuel later. Your garage saves with your story.</p></section>`;
  function finish(result){if(result.ok)renderGarage(host,context);context.notify(result.message);}
  $('#chooseWalking').onclick=()=>finish(chooseTransport('walk'));host.querySelectorAll('[data-buy-ride]').forEach(b=>b.onclick=()=>finish(buyVehicle(b.dataset.buyRide)));host.querySelectorAll('[data-choose-ride]').forEach(b=>b.onclick=()=>finish(chooseTransport(b.dataset.chooseRide)));host.querySelectorAll('[data-refuel]').forEach(b=>b.onclick=()=>finish(refuelVehicle(b.dataset.refuel)));
 }
 function renderApp(app,host,context){({map:renderMap,bank:renderBank,jobs:renderJobs,garage:renderGarage,shop:renderShop,notes:renderNotes}[app])?.(host,context);}
 window.KoraPhoneApps={apps:APPS,isLocal:app=>LOCAL.has(app),renderHome,renderApp,rentInfo};
})();
